"""
backend/app/schemas/pest_forecasting.py
──────────────────────────────────────
Pydantic schemas for experimental Version 2.0 multi-crop pest outbreak forecasting.
Strictly partitioned from production-certified agricultural advisories.
"""
from __future__ import annotations

from typing import Any
from pydantic import BaseModel, Field, model_validator


SCIENTIFIC_PEST_DISCLAIMER = (
    "SYNTHETIC EXPERIMENTAL MODEL ONLY: This outbreak risk prediction is generated by "
    "an experimental machine learning model trained exclusively on synthetic biophysical "
    "simulation data (Phase 21). It is NOT a calibrated real-world outbreak probability "
    "and must NOT be used for commercial, legal, or operational field pesticide spraying decisions."
)


class PestForecastingRequest(BaseModel):
    """Input payload for 7-day pest outbreak forecasting."""
    configuration: str = Field(
        default="ENVIRONMENTAL_ONLY",
        description="Feature configuration: 'ENVIRONMENTAL_ONLY' or 'SCOUTING_ASSISTED'",
    )
    crop: str = Field(default="Cotton", description="Cultivated crop (e.g. Cotton, Rice, Maize, Soybean)")
    pest: str = Field(default="Pink bollworm", description="Target pest species")
    district: str = Field(default="Nagpur", description="Geographic district (Maharashtra)")
    growth_stage: str = Field(default="Squaring", description="Crop growth / phenological stage")

    # 7-day Antecedent Environmental & Soil Features
    t7_mean_temp_c: float = Field(..., ge=-15.0, le=60.0, description="7-day mean temperature (°C)")
    t7_min_temp_c: float = Field(..., ge=-20.0, le=55.0, description="7-day minimum temperature (°C)")
    t7_max_temp_c: float = Field(..., ge=-10.0, le=65.0, description="7-day maximum temperature (°C)")
    t7_mean_rh_pct: float = Field(..., ge=0.0, le=100.0, description="7-day mean relative humidity (%)")
    t7_rainfall_mm: float = Field(..., ge=0.0, le=2000.0, description="7-day cumulative rainfall (mm)")
    t14_rainfall_mm: float = Field(..., ge=0.0, le=4000.0, description="14-day cumulative rainfall (mm)")
    t7_mean_soil_moisture: float = Field(..., ge=0.0, le=1.0, description="7-day mean topsoil moisture (m³/m³)")
    t7_high_rh_days: int = Field(..., ge=0, le=7, description="Count of days in past week with RH >= 80%")
    t7_consecutive_dry_days: int = Field(..., ge=0, le=7, description="Consecutive dry days (rainfall < 1mm)")

    # Optional In-Field Scouting Features (Required for SCOUTING_ASSISTED)
    scout_incidence_pct: float | None = Field(default=None, ge=0.0, le=100.0, description="Observed infested plants (%)")
    scout_severity_pct: float | None = Field(default=None, ge=0.0, le=100.0, description="Observed foliage/tissue damage (%)")
    trap_catch_count: float | None = Field(default=None, ge=0.0, description="Pheromone / light trap catch count")
    days_since_scouting: float | None = Field(default=None, ge=0.0, description="Days elapsed since field inspection")
    pest_present: int | None = Field(default=None, ge=0, le=1, description="Binary insect presence indicator (0 or 1)")

    @model_validator(mode="after")
    def validate_biological_and_mode_consistency(self) -> PestForecastingRequest:
        # Physical consistency checks
        if self.t7_min_temp_c > self.t7_max_temp_c:
            raise ValueError("t7_min_temp_c cannot exceed t7_max_temp_c.")
        if self.t7_rainfall_mm > self.t14_rainfall_mm:
            raise ValueError("7-day rainfall cannot exceed 14-day cumulative rainfall.")

        norm_cfg = self.configuration.strip().upper()
        if norm_cfg not in ("ENVIRONMENTAL_ONLY", "SCOUTING_ASSISTED"):
            raise ValueError("configuration must be either 'ENVIRONMENTAL_ONLY' or 'SCOUTING_ASSISTED'.")

        # Scouting requirements
        if norm_cfg == "SCOUTING_ASSISTED":
            missing_fields = []
            if self.scout_incidence_pct is None:
                missing_fields.append("scout_incidence_pct")
            if self.scout_severity_pct is None:
                missing_fields.append("scout_severity_pct")
            if self.trap_catch_count is None:
                missing_fields.append("trap_catch_count")
            if self.days_since_scouting is None:
                missing_fields.append("days_since_scouting")
            if self.pest_present is None:
                missing_fields.append("pest_present")

            if missing_fields:
                raise ValueError(
                    f"SCOUTING_ASSISTED configuration requires in-field scouting observations. "
                    f"Missing fields: {missing_fields}."
                )

        return self


class PestForecastingResponse(BaseModel):
    """Output payload for experimental pest forecasting inference."""
    classification: str = "SYNTHETIC_EXPERIMENTAL"
    is_production_ready: bool = False
    feature_configuration: str
    outbreak_risk_probability: float
    outbreak_warning: bool
    decision_threshold: float
    risk_level: str
    model_version: str
    model_family: str
    prediction_horizon_days: int = 7
    disclaimer: str = SCIENTIFIC_PEST_DISCLAIMER
    input_summary: dict[str, Any]


class PestModelInfoResponse(BaseModel):
    """Metadata response describing active experimental pest models."""
    service_status: str
    environmental_model_available: bool
    scouting_model_available: bool
    model_version: str
    classification: str = "SYNTHETIC_EXPERIMENTAL"
    is_production_ready: bool = False
    production_readiness_status: str = "BLOCKED"
    environmental_model_type: str
    scouting_model_type: str
    decision_thresholds: dict[str, float]
    feature_schemas: dict[str, Any]
    disclaimer: str = SCIENTIFIC_PEST_DISCLAIMER
